def move_legacy_claims_to_manual_review(apps, schema_editor):
    """Claims still waiting on the old quiz go to staff review; open quizzes are closed.
    Old answers and attempts are kept (audit), they just no longer gate anything."""
    Claim = apps.get_model("lostfound", "Claim")
    Challenge = apps.get_model("lostfound", "VerificationChallenge")
    pending = Claim.objects.filter(status="pending_verification")
    Challenge.objects.filter(claim__in=pending, status="open").update(status="cancelled")
    pending.update(status="under_review")


def raise_return_bonus(apps, schema_editor):
    """New default return bonus is 40; only touch the policy if it still has the old default."""
    RewardPolicy = apps.get_model("lostfound", "RewardPolicy")
    RewardPolicy.objects.filter(points_return=25).update(points_return=40)


